CREATE OR REPLACE FUNCTION public.log_recurrence_pattern_changes() RETURNS trigger LANGUAGE plpgsql AS $fn$ BEGIN INSERT INTO public.audit_logs (hospital_id, user_id, action, table_name, record_id, changes, created_at) VALUES (NEW.hospital_id, auth.uid(), TG_OP, 'appointment_recurrence_patterns', NEW.id, jsonb_build_object('old', to_jsonb(OLD), 'new', to_jsonb(NEW)), now()); RETURN NEW; END; $fn$; DROP TRIGGER IF EXISTS trg_log_recurrence_changes ON public.appointment_recurrence_patterns; CREATE TRIGGER trg_log_recurrence_changes AFTER INSERT OR UPDATE OR DELETE ON public.appointment_recurrence_patterns FOR EACH ROW EXECUTE FUNCTION public.log_recurrence_pattern_changes();